public class OutboxRelay(IServiceScopeFactory scopes, Channel<string> outbox) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (string msg in outbox.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                using IServiceScope scope = scopes.CreateScope();
                Publisher publisher = scope.ServiceProvider.GetRequiredService<Publisher>();
                await publisher.PublishAsync(msg, stoppingToken);
            }
            catch (Exception ex) when (!stoppingToken.IsCancellationRequested)
            {
                // log + dead-letter; never let one message kill the host
            }
        }
    }
}
